{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The aws_instance resource does not have the 'ebs_block_device' or 'root_block_device' attribute with 'encrypted' set to true, potentially leaving EBS volumes unencrypted."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The aws_instance resource does not have the 'metadata_options' attribute configured, potentially allowing IMDSv1."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The aws_instance resource does not have an 'iam_instance_profile' attribute set, potentially leaving the instance without an IAM role."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n  iam_instance_profile = \"default-ec2-profile\"\n}",
  "fix_summary": "Added 'metadata_options' to disable IMDSv1, 'root_block_device' with 'encrypted' set to true for EBS encryption, and 'iam_instance_profile' to attach an IAM role to the EC2 instance."
}
